/* Browsable portfolio files plus read-only folders explicitly chosen by visitors. */
(() => {
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const nodes=new Map(Object.entries(window.PortfolioFiles?.nodes||{})),states=new WeakMap();let localSerial=0,blob=null,previewFile=null;
const icon=n=>n.icon||({folder:'folder',video:'folder-open',image:'projects',text:'socials',download:'folder',link:'safari',view:'finder'}[n.kind]||'folder');
const bytes=n=>!n?'—':n>1048576?(n/1048576).toFixed(1)+' MB':n>1024?Math.round(n/1024)+' KB':n+' B';
function initial(){return {path:'home',history:['home'],position:0,mode:'grid',query:''}}
function state(browser){if(!states.has(browser)){let saved='grid';try{saved=localStorage.getItem('po-finder-view')||'grid'}catch{}states.set(browser,{...initial(),mode:saved==='list'?'list':'grid'})}return states.get(browser)}
function trail(id){const chain=[];let n=nodes.get(id),guard=0;while(n&&guard++<30){chain.unshift(n);n=nodes.get(n.parent)}return chain}
function markup(s){const node=nodes.get(s.path)||nodes.get('home'),files=(node.children||[]).map(id=>nodes.get(id)).filter(Boolean).filter(n=>n.name.toLowerCase().includes(s.query.toLowerCase())).sort((a,b)=>(b.kind==='folder')-(a.kind==='folder')||a.name.localeCompare(b.name));
return `<div class="files-toolbar"><div><button data-file-back aria-label="Back" ${s.position===0?'disabled':''}>‹</button><button data-file-forward aria-label="Forward" ${s.position>=s.history.length-1?'disabled':''}>›</button><button data-file-up aria-label="Enclosing folder" ${!node.parent?'disabled':''}>↑</button></div><strong>${esc(node.name)}</strong><div class="files-view-buttons"><button data-file-mode="grid" aria-label="Icon view" aria-pressed="${s.mode==='grid'}">▦</button><button data-file-mode="list" aria-label="List view" aria-pressed="${s.mode==='list'}">☷</button></div><label class="files-search"><span>⌕</span><input data-file-search aria-label="Search this folder" placeholder="Search this folder" value="${esc(s.query)}"></label></div><div class="files-location"><nav aria-label="Folder path">${trail(node.id).map(n=>`<button data-file-folder="${esc(n.id)}">${esc(n.name)}</button>`).join('<span>›</span>')}</nav><button data-file-local>Open a folder…</button></div><div class="files-items files-${s.mode}" role="list" aria-label="${esc(node.name)} files">${files.map(n=>`<button role="listitem" class="files-item" data-file-id="${esc(n.id)}" aria-label="${esc(n.name)} · ${n.kind==='folder'?'folder':n.kind}"><span class="files-item-art">${n.kind==='image'&&n.src?`<img src="${esc(n.src)}" alt="" loading="lazy">`:`<img src="${icon(n)==='games'?'assets/ps-app/icon.svg':'assets/tahoe/'+icon(n)+'.svg'}" alt="">`}${n.kind==='video'?'<b>▶</b>':''}</span><span class="files-item-name">${esc(n.name)}</span><small>${n.kind==='folder'?(n.children?.length||0)+' items':bytes(n.size)}</small><em>${n.kind==='folder'?'Folder':n.label||n.kind}</em></button>`).join('')||'<p class="files-empty">'+(s.query?'No matching files.':'This folder is empty.')+'</p>'}</div><footer class="files-footer"><span>${files.length} ${files.length===1?'item':'items'}</span><span>${node.local?'Selected folder · read-only':'Portfolio files · click a folder to explore'}</span></footer>`}
views.files={title:'Finder',status:'Browse portfolio folders, pictures and videos',keywords:'finder file files browser folders pictures movies videos documents downloads local',render:()=>'<section class="file-browser">'+markup(initial())+'</section>'};
const dock=document.querySelector('.dock-finder');dock.dataset.open='files';dock.setAttribute('aria-label','Finder — browse files');dock.querySelector('small').textContent='Finder';
const side=document.querySelector('.finder-sidebar');side.insertAdjacentHTML('afterbegin','<button data-open="files"><img class="tahoe-sidebar-icon" src="assets/tahoe/finder.svg" alt=""><span>Finder / All files</span></button>');
function render(browser){const s=state(browser);browser.innerHTML=markup(s);if(browser.closest('#finder')){document.querySelector('#window-title').textContent=nodes.get(s.path)?.name||'Finder';document.querySelector('#window-status').textContent=(nodes.get(s.path)?.children?.length||0)+' items'} }
async function loadFolder(node){if(!node.handle||node.loaded)return;const children=[];for await(const [name,handle]of node.handle.entries()){const id='local-'+(++localSerial),kind=handle.kind==='directory'?'folder':fileKind(name);nodes.set(id,{id,name,kind,parent:node.id,handle,children:kind==='folder'?[]:undefined,local:true});children.push(id)}node.children=children;node.loaded=true}
async function navigate(browser,id,push=true){const node=nodes.get(id);if(node?.kind!=='folder')return;try{await loadFolder(node);const s=state(browser);s.path=id;s.query='';if(push){s.history=s.history.slice(0,s.position+1);s.history.push(id);s.position++}render(browser)}catch{notify('This folder could not be opened. Choose it again to renew access.')}}
function fileKind(name){return /\.(png|jpe?g|webp|gif|svg|avif)$/i.test(name)?'image':/\.(mp4|webm|mov|m4v|ogg)$/i.test(name)?'video':/\.(txt|md|json|js|ts|css|html|csv)$/i.test(name)?'text':'download'}
const preview=document.createElement('dialog');preview.id='finder-preview';preview.setAttribute('aria-labelledby','file-preview-title');preview.innerHTML='<header><div><img src="assets/tahoe/projects.svg" alt=""><strong id="file-preview-title"></strong></div><button id="file-preview-close" aria-label="Close preview">Close ×</button></header><div class="file-preview-body"></div><footer><span id="file-preview-info"></span><a id="file-preview-download" download>Download file ↓</a></footer>';document.body.append(preview);
function stopPreview(){preview.querySelectorAll('video').forEach(v=>{v.pause();v.removeAttribute('src');v.load?.()});if(blob){URL.revokeObjectURL(blob);blob=null}previewFile=null;preview.querySelector('.file-preview-body').replaceChildren()}
preview.querySelector('#file-preview-close').onclick=()=>preview.close();preview.addEventListener('close',stopPreview);preview.addEventListener('cancel',()=>stopPreview());
async function openFile(node){if(node.kind==='view'){openView(node.view);return}if(node.kind==='link'){if(node.src.startsWith('https://'))window.open(node.src,'_blank','noopener,noreferrer');else location.href=node.src;window.dispatchEvent(new CustomEvent('portfolio:notification',{detail:{title:'Project opened',body:node.name,action:'files'}}));return}
 stopPreview();previewFile=node;const body=preview.querySelector('.file-preview-body');body.textContent='Opening file…';preview.querySelector('#file-preview-title').textContent=node.name;if(!preview.open)preview.showModal();
 try{let file=node.file;if(node.handle)file=await node.handle.getFile();if(previewFile!==node)return;let src=node.src;if(file){blob=URL.createObjectURL(file);src=blob;node.size=file.size}preview.querySelector('#file-preview-info').textContent=(node.label||node.kind)+' · '+bytes(node.size);const download=preview.querySelector('#file-preview-download');download.href=src;download.download=node.name;body.replaceChildren();
  if(node.kind==='image'){const img=document.createElement('img');img.src=src;img.alt=node.name;body.append(img)}
  else if(node.kind==='video'){const video=document.createElement('video');video.controls=true;video.autoplay=true;video.muted=true;video.loop=true;video.playsInline=true;video.preload='auto';video.src=src;if(node.poster)video.poster=node.poster;const status=document.createElement('p');status.className='file-video-status';status.textContent='Playing with sound off · use the controls to unmute';video.addEventListener('playing',()=>window.dispatchEvent(new CustomEvent('portfolio:notification',{detail:{title:'Video playing',body:node.local?'A local video is playing with sound off.':node.name+' is playing with sound off.',action:'files'}})),{once:true});video.addEventListener('error',()=>status.textContent='This video could not load. Try Download file.');body.append(video,status);video.play().catch(()=>status.textContent='Press Play to start this video. Sound is off.');}
  else if(node.kind==='text'){const pre=document.createElement('pre');if((file?.size||node.size)>250000){pre.textContent='This text file is large. Download it to view the full content.'}else pre.textContent=file?await file.text():await(await fetch(src)).text();if(previewFile===node)body.append(pre)}
  else{const info=document.createElement('div');info.className='file-download-preview';info.innerHTML='<img src="assets/tahoe/folder.svg" alt=""><h2>Ready to download.</h2><p>This file opens in its compatible application.</p>';body.append(info)}
 }catch{if(previewFile===node)body.textContent='This file could not be opened. Try selecting the folder again.'}}
async function localFolder(browser){
 if(window.showDirectoryPicker){try{const handle=await window.showDirectoryPicker({mode:'read'}),id='local-'+(++localSerial),node={id,name:handle.name,kind:'folder',parent:'home',children:[],handle,local:true};nodes.set(id,node);nodes.get('home').children.push(id);await navigate(browser,id);return}catch(e){if(e.name==='AbortError')return;if(e.name!=='SecurityError'&&e.name!=='NotAllowedError'){notify('Folder access failed. Try choosing a folder again.');return}}}
 const input=document.createElement('input');input.type='file';input.multiple=true;input.setAttribute('webkitdirectory','');input.hidden=true;document.body.append(input);input.addEventListener('change',()=>{const files=[...input.files];if(!files.length){input.remove();return}const rootId='local-'+(++localSerial),rootName=files[0].webkitRelativePath.split('/')[0]||'Selected folder';nodes.set(rootId,{id:rootId,name:rootName,kind:'folder',parent:'home',children:[],local:true});nodes.get('home').children.push(rootId);const folders=new Map([['',rootId]]);for(const file of files){const parts=file.webkitRelativePath.split('/').slice(1),name=parts.pop();let current=rootId,path='';for(const part of parts){path+=(path?'/':'')+part;if(!folders.has(path)){const id='local-'+(++localSerial);nodes.set(id,{id,name:part,kind:'folder',parent:current,children:[],local:true});nodes.get(current).children.push(id);folders.set(path,id)}current=folders.get(path)}const id='local-'+(++localSerial);nodes.set(id,{id,name:name||file.name,kind:fileKind(name||file.name),parent:current,size:file.size,file,local:true});nodes.get(current).children.push(id)}navigate(browser,rootId);input.remove()},{once:true});input.click();
}
document.addEventListener('click',e=>{const browser=e.target.closest('.file-browser');if(!browser)return;const s=state(browser),b=e.target.closest('button');if(!b)return;
 if(b.hasAttribute('data-file-local')){localFolder(browser);return}if(b.dataset.fileFolder){navigate(browser,b.dataset.fileFolder);return}
 if(b.dataset.fileId){const node=nodes.get(b.dataset.fileId);if(node?.kind==='folder')navigate(browser,node.id);else if(node)openFile(node);return}
 if(b.hasAttribute('data-file-back')&&s.position>0){s.position--;navigate(browser,s.history[s.position],false)}if(b.hasAttribute('data-file-forward')&&s.position<s.history.length-1){s.position++;navigate(browser,s.history[s.position],false)}if(b.hasAttribute('data-file-up')){const parent=nodes.get(s.path)?.parent;if(parent)navigate(browser,parent)}if(b.dataset.fileMode){s.mode=b.dataset.fileMode;try{localStorage.setItem('po-finder-view',s.mode)}catch{}render(browser)}
});
document.addEventListener('input',e=>{if(!e.target.matches('[data-file-search]'))return;const browser=e.target.closest('.file-browser'),s=state(browser);s.query=e.target.value;const position=e.target.selectionStart;render(browser);const input=browser.querySelector('[data-file-search]');input.focus();input.setSelectionRange?.(position,position)});
document.addEventListener('keydown',e=>{if(preview.open)return;const browser=e.target.closest('.file-browser');if(!browser)return;if(e.altKey&&e.key==='ArrowLeft'){e.preventDefault();browser.querySelector('[data-file-back]').click()}if(e.altKey&&e.key==='ArrowRight'){e.preventDefault();browser.querySelector('[data-file-forward]').click()}if(e.altKey&&e.key==='ArrowUp'){e.preventDefault();browser.querySelector('[data-file-up]').click()}});
preview.querySelector('#file-preview-download').addEventListener('click',()=>window.dispatchEvent(new CustomEvent('portfolio:notification',{detail:{title:'Download requested',body:previewFile?.name||'Portfolio file',action:'files'}})));
document.addEventListener('visibilitychange',()=>{preview.querySelectorAll('video').forEach(v=>{if(document.hidden)v.pause();else if(preview.open){v.muted=true;v.play().catch(()=>{})}})});document.querySelector('#lock-button').addEventListener('click',()=>{if(preview.open)preview.close()});
window.PortfolioFinder={open(){openView('files')},get catalogue(){return [...nodes.values()].map(n=>({id:n.id,name:n.name,kind:n.kind,src:n.src}))}};
})();
